function conditionTimingMarkup(c){const t=conditionTiming(c),qualification={forward:'窗口开始前已登记',during_window:'观察窗口中形成，不是前向条件',retrospective:'观察窗口结束后形成，属于复盘条件',unknown:'前向登记资格未知'}[t.timingQualification]||'前向登记资格未知',registration=t.registrationBasis==='service-recorded'?'服务登记 '+when(t.registeredAt):t.registrationBasis==='legacy-report-generated-at'?'旧报告生成 '+when(c.createdAt)+'；只能作时序参考，不能证明前向登记':'登记时间未知';return `<div class="at-condition-timing" data-condition="${esc(c.id)}" data-timing-qualification="${esc(t.timingQualification)}"><strong>${esc(qualification)}</strong><p>${esc(registration)}<br>观察窗口 ${Number.isSafeInteger(c.from)?when(c.from):'未知'} → ${Number.isSafeInteger(c.to)?when(c.to):'未知'}<br>期限 ${when(c.deadline)} · 检查资料 ${when(c.checkedAt)}</p><small>登记时点不证明用户当时已看到，也不证明预测效果。</small></div>`;}
function conditionRows(rows,cycleId){return rows.map(c=>`<article><div class="at-report-head"><strong>${esc(c.text||'待核查条件')}</strong><span class="at-status">${esc({unknown:c.kind==='manual'?'待人工核查':'未知',triggered:'已触发',not_triggered:'未触发',expired:'已到期'}[c.state]||'未知')}</span></div><p>${esc(readable(c.reason||'没有取得足以判断的新资料。'))}</p>${c.kind==='deterministic'?conditionTimingMarkup(c):''}<div class="at-evidence-actions">${c.parentReportId?`<button class="btn" data-previous="${esc(c.parentReportId)}">原判断</button>`:''}${cycleId?(c.evidenceIds||[]).map(id=>`<button class="btn" data-evidence="${esc(id)}" data-cycle="${esc(cycleId)}">检查依据</button>`).join(''):''}</div></article>`).join('');}
export function conditionChecksCard(rows,cycleId){rows=rows?.filter(c=>c.kind==='deterministic');if(!rows?.length)return '';const actionable=rows.filter(c=>c.kind==='deterministic'&&['triggered','expired'].includes(c.state));return `<details class="at-condition-checks" ${actionable.length?'open':''}><summary>机器可核查条件的本次检查 · ${rows.length} 项${actionable.length?' · '+actionable.length+' 项需要关注':''}</summary><p class="muted">状态依据实际检查回执；资料范围不足时保持未知。</p><div class="at-conditions">${conditionRows(rows,cycleId)}</div></details>`;}
function readerMarkup(){return '<dialog id="at-dialog" aria-label="当时报告与原始依据"><div class="at-dialog-tools"><button class="btn" id="at-close">关闭</button><button class="btn" id="at-export" disabled>导出当前记录</button></div><div id="at-detail"></div></dialog>';}
function roleResultCard(record){const slot=record.result,previous=slot?.previousId;return `<section class="at-evidence" data-testid="role-result"><h2>${esc(ROLES[record.role]?.name||record.role)} · 当时岗位结果</h2><p class="at-status">${esc(labels[slot?.status]||slot?.status||'未取得')}</p><p class="at-warning">本轮没有已接受报告，保留缺口。</p><p class="at-thesis">${esc(readable(slot?.report?.summary||(slot?.error?friendlyError(slot.error):'没有取得该岗位的研究结果。')))}</p><p class="muted">研究锚点 ${when(record.asOf)} · 本轮结束 ${when(record.endedAt)}</p>${taskCard(record.task,{compact:true})}${previous?`<button class="btn" data-previous="${esc(previous)}">上次已接受判断（非本轮）</button>`:''}<details><summary>完整当时岗位记录</summary><pre>${esc(JSON.stringify(record,null,2))}</pre></details></section>`;}
