function currentAttempt(state){const active=state.active?.task?.taskMode&&state.active.task.taskMode!=='current'?null:state.active,last=state.lastAttempt?.task?.taskMode&&state.lastAttempt.task.taskMode!=='current'?null:state.lastAttempt;return active||last;}
