  const recovery=document.createElement('section');recovery.className='at-warning';recovery.hidden=true;recovery.id='at-cleanup-recovery';recovery.innerHTML='<h3>研究等待退出核对</h3><p>上一轮未能确认所有研究进程已退出。核对本机原进程身份后可以解除暂停；原失败记录与最后已接受观点会保留。</p><button class="btn" type="button" id="at-recover-cleanup">核对退出并解除暂停</button>';
